from h import *
R(9491703,"كرات الطاقة بالماتشا",
"عزّز يومك بكرات الماتشا الخضراء هذه للطاقة بدون خبز.",
"20 كرة","حصة واحدة",
["1 كوب تمر منزوع النوى غير مكبوس","1 كوب كاجو نيء","2 ملعقة كبيرة بروتين بذور القرع المسحوق أو مسحوق بروتين من اختيارك أو دقيق اللوز","1 ملعقة كبيرة مسحوق الماتشا","1 ملعقة صغيرة مستخلص الفانيليا الطبيعي","2-4 ملاعق كبيرة ماء","¼ كوب فستق مفروم لتغليف الكرات"],
["ضع كل شيء ما عدا الماء في محضّر الطعام وقلّب بالنبض حتى يتفتت كل شيء دون أن يتحول إلى هريس. ثم أضف ملعقتين كبيرتين من الماء وقلّب بالنبض حتى تمتزج.","المس الخليط، وإذا كان لزجًا بما يكفي لتشكيله إلى كرات، فلا تضف مزيدًا من الماء. وإذا كان لا يزال جافًا، فأضف ملعقة صغيرة أخرى في كل مرة حتى تتمكن من تشكيله إلى كرات.","شكّل الخليط إلى كرات صغيرة بحجم اللقمة، بحوالي ملعقة كبيرة من الخليط لكل كرة. ستحصل على حوالي 20 حصة.","اختياري: لفّ بعض الكرات أو كلها في خليط الفستق المجروش إن أحببت.","ضعها في الثلاجة لمدة ساعة أو أكثر واستمتع بها."],
["إذا كان التمر جافًا جدًا، فانقعه في ماء ساخن لمدة 10-15 دقيقة، ثم صفّه قبل إضافته إلى محضّر الطعام. فهذا سيساعد على تليينه وتسهيل فرمه.","لا تُفرط في فرم الخليط. فطعم كرات الطاقة بالماتشا هذه أفضل مع قليل من القوام.","استخدم يدين مبللتين قليلًا لتشكيل الكرات لمنع الالتصاق. سيكون الخليط لزجًا، وهذا طبيعي."],
{"Optional":"اختياري"})
R(9492507,"روست نباتي بالفطر",
"روست نباتي غني جدًا باللحم وبنكهات الأومامي بفضل الفطر ومعجون الميسو، هو الروست النباتي المثالي الذي يسيل له اللعاب.",
"8 حصص","حصة واحدة",
["1 كوب فاصولياء كانيليني بيضاء","عبوة 227 جرامًا (8 أونصات) فطر كريميني أو بيبي بيلا","¾ كوب مرق خضار (استخدم مرقًا مالحًا وجيد النوعية وغنيًا بالنكهة)","4 فصوص ثوم مقشّرة","1 ملعقة كبيرة معجون الميسو الأبيض","1 ملعقة كبيرة طحينة","¼ كوب خميرة غذائية","2 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة مريمية مجففة","1 ملعقة صغيرة زعتر مجفف","1 ملعقة صغيرة إكليل الجبل المجفف المجروش","½ ملعقة صغيرة فلفل أسود","280 جرامًا من غلوتين القمح الحيوي، أي حوالي 2¼ كوب"],
["ضع جميع المكونات ما عدا غلوتين القمح الحيوي في محضّر الطعام واخلطها حتى تصبح ناعمة في معظمها. ثم أضف غلوتين القمح الحيوي، نصف الكمية في كل مرة، وقلّب بالنبض حتى تمتزج في معظمها. (ليس من الضروري أن تكون مثالية.)","انقل الخليط إلى لوح تقطيع نظيف أو سطح نظيف آخر. ثم اعجن العجينة بيديك لمدة 2-3 دقائق. شكّلها على هيئة أسطوانة بعرض 4 بوصات وطول 8 بوصات تقريبًا.","لفّها بإحكام بورق الزبدة ثم بورق الألمنيوم والتف الأطراف لتثبيتها. (انظر صور خطوات التحضير أعلاه للرجوع إليها.) ثم اختر طريقة طهي واحدة فقط من الطرق أدناه.","ضع كوبًا من الماء في قاع Instant Pot وضع حامل التبخير فوقه. ثم ضع الروست النباتي الملفوف على الحامل. أغلق الغطاء، وتأكد من أن الصمام في وضع الإغلاق، واضبطه على \"البخار\" لمدة 60 دقيقة. اترك القدر يُطلق الضغط طبيعيًا ثم افتحه عندما يكون ذلك آمنًا. (سيستغرق الإطلاق الطبيعي حوالي 10-12 دقيقة.) انقل الروست إلى لوح تقطيع واتركه يرتاح لمدة 10 دقائق قبل التقطيع.","سخّن الفرن مسبقًا على 375° فهرنهايت (190° مئوية) وضع روست السيتان الملفوف على صينية خبز. اخبزه على الرف الأوسط لمدة 45 دقيقة. ثم اقلبه واخبزه لمدة 45 دقيقة إضافية. أخرجه من الفرن واتركه يرتاح لمدة 10 دقائق قبل التقطيع.","اغلِ قدرًا كبيرًا فيه بضع بوصات من الماء وضع سلة التبخير بداخله. تأكد من أن السلة لا تلامس الماء. وعندما يغلي، اخفض الحرارة للحفاظ على غليان خفيف/نار هادئة، وضع الروست النباتي الملفوف بداخلها، وضع الغطاء فوقها. اطهِه على البخار لمدة 35 دقيقة، ثم اقلبه واطهِه على البخار 35-45 دقيقة إضافية. تفقّد مستوى الماء من حين لآخر وأضف ماءً ساخنًا عند الحاجة. وبعد النضج، انقل الروست النباتي إلى لوح تقطيع واتركه يرتاح لمدة 10 دقائق قبل التقطيع."],
["زِن غلوتين القمح الحيوي للحصول على أدق النتائج. وإذا اضطررت إلى القياس بالأكواب، فتأكد من وضع الدقيق بالملعقة وتسوية سطحه. لا تغترفه من الكيس وإلا ستنتهي بكمية أكثر من اللازم.","احرص على استخدام مرق غني بالنكهة ومالح لأنه لا يُضاف أي ملح آخر. وإذا كان لديك مرق قليل الصوديوم فقط، فأضف ½-1 ملعقة صغيرة من الملح.","لاختبار النضج: اسحب ورق الألمنيوم برفق، يجب أن يبدو روست السيتان أملس. اضغط عليه بإصبعك أو بملقط لاختبار تماسكه. (احذر، سيكون ساخنًا!) يجب أن يبدو متماسكًا لكنه يلين قليلًا عند الضغط. وسيواصل التماسك عندما يبرد.","يبقى المتبقي صالحًا في الثلاجة لمدة تصل إلى 5 أيام. أو جمّد الروست النباتي في وعاء محكم الإغلاق مناسب للتجميد لمدة تصل إلى 3 أشهر. يمكنك تجميده كاملًا أو شرائح."],
{"Instant Pot Instructions":"طريقة التحضير في Instant Pot","Baking Instructions":"طريقة الخَبز","Steaming Instructions":"طريقة الطهي على البخار"})
R(9497075,"عصير الكرفس والأناناس",
"لا شيء يضاهي العصير الطازج، وعصير الكرفس والأناناس هذا رائع بكل معنى الكلمة!!",
"3 حصص (يعطي حوالي 3½ أكواب)","حصة واحدة",
["1 رطل أناناس، أي حوالي نصف حبة أناناس متوسطة","1 رطل كرفس، أي حوالي 4 أعواد كبيرة","1 حبة تفاح غراني سميث متوسطة مقطعة أرباعًا ومنزوعة البذور","½ بوصة زنجبيل طازج"],
["اغسل المنتجات جيدًا وقطّع الأناناس إلى أصابع أو قطع. أعواد الكرفس تناسب الجهاز دون تقطيع. ثم قطّع التفاحة أرباعًا وانزع البذور.","ابدأ بعصر الأناناس أولًا ثم أتبعه بالتفاح والزنجبيل والكرفس.","حرّك العصير بسرعة واستمتع به فورًا."],
["لا تستخدم الخلاط. فالخلاط يصنع سموذي وليس عصيرًا. استخدم عصارة بطيئة (ماضغة) عالية الجودة، مثل Sana 727 للحصول على أفضل النتائج. فالعصارات الماضغة (أو البطيئة) تستخرج العصير ببطء ولا تضيف حرارة. فالحرارة قد تتلف العناصر الغذائية في المنتجات فلا تحصل على الفائدة الكاملة. حضّر كمية العصير التي تنوي شربها، وليس أكثر. فالعصير الطازج الخالي من المواد الحافظة لا يبقى طويلًا، وللحصول على أقصى فوائد صحية، يجب تناوله فورًا. لتسريع وقت تحضير العصر، يمكنك غسل المنتجات وتقطيعها في الليلة السابقة وحفظها في الثلاجة في وعاء محكم الإغلاق. ثم في الصباح، تكون الفواكه والخضار جاهزة لتمريرها عبر العصارة."])
R(9498029,"شوربة البطاطا الحلوة بالتوابل",
"لذيذة وكريمية و حارة فعلًا! شوربة البطاطا الحلوة بالتوابل هذه مشبعة وغنية بالنكهة ودافئة بشكل لا يصدق، ومثالية لعشاء الخريف (أو أي وقت).",
"6 حصص","حصة واحدة",
["1 حبة بصل أصفر مقشّرة ومقطعة أرباعًا","1 فلفل هالبينو","2 رطل بطاطا حلوة مقشّرة ومقطعة مكعبات بحجم 1 بوصة (حوالي 4 حبات متوسطة، أو 5 أكواب مكعبات)","1½ رطل قرع الجوز (أكورن) مقشّر ومقطع مكعبات بحجم 1 بوصة (حوالي حبة قرع صغيرة أو 3 أكواب مكعبات)","4 أكواب زهيرات قرنبيط، أي حوالي قرنبيطة صغيرة","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق الفلفل الحار","¼ ملعقة صغيرة قرفة","¼ ملعقة صغيرة زنجبيل مطحون","6 أكواب مرق خضار قليل الصوديوم","ملح + فلفل حسب الرغبة","كريمة الكاجو","ثوم معمر (شيف) أو بقدونس"],
["سخّن الفرن مسبقًا على 450 درجة فهرنهايت (230 درجة مئوية) بوضع الخَبز بالهواء الساخن.","رتّب الخضار المجهزة على صينية خبز كبيرة مبطّنة بورق الزبدة. رشّها بسخاء بالملح والفلفل. ثم اخبزها لمدة 20-25 دقيقة، حتى تلين عند غرزها بالشوكة وتصبح ذهبية.","اقطع ساق الهالبينو وانقل الخضار المطبوخة إلى قدر مع المرق وجميع التوابل. اهرسها باستخدام الخلاط اليدوي. أو استخدم خلاطًا عاديًا، مع العمل على دفعات لهرس الشوربة.","قدّمها مزينة بكريمة الكاجو والأعشاب الطازجة إن رغبت."],
["لتقليل الحرارة، أزل البذور من الهالبينو قبل خلطه في الشوربة. زِن البطاطا الحلوة والقرع للحصول على أفضل النتائج. فبما أن أحجام البطاطا الحلوة والقرع تختلف كثيرًا، فإن الوزن يعطي القوام الأدق. إذا كان لديك خلاط يدوي، فيمكنك نقل الخضار المحمّصة والمكونات المتبقية إلى قدر وهرس الشوربة دفعة واحدة. وللخلط بخلاط عادي، اعمل على عدد الدفعات اللازم. (تمكنت من فعل ذلك على دفعتين.) فقط احرص على الاحتفاظ ببعض المرق لكل دفعة، فخلاطك سيحتاج إلى بعض السائل لهرس الشوربة. وبعد هرس كل دفعة، انقلها إلى قدر أو طبق كبير بما يكفي لاستيعاب كل الشوربة وقلّب جيدًا لتوزيع التوابل بالتساوي. لتوفير وقت التحضير، يمكنك شراء القرع والبطاطا الحلوة المقطعين مسبقًا إلى مكعبات من متجر البقالة. أو يمكنك التحضير مسبقًا بتقشير الخضار وتقطيعها قبل يومين كحد أقصى. يبقى المتبقي صالحًا في الثلاجة لمدة 3 أيام أو يمكنك تجميده لمدة تصل إلى 3 أشهر."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9506425,"صلصة معكرونة الشمندر المحمّص",
"صلصة معكرونة الشمندر النباتية هذه طبق زاهٍ وكريمي مصنوع من الشمندر المحمّص والثوم والبصل ومرق الخضار، مخلوطة حتى تصبح بقوام ناعم.",
"4 حصص","حصة واحدة",
["3 أكواب شمندر مقطع مكعبات، أي حوالي حبتي شمندر متوسطتين","1 حبة بصل أصفر مقطعة أرباعًا","4 فصوص ثوم اترك القشر عليها!","1 كوب مرق خضار","⅓ كوب كاجو نيء","1 ملعقة كبيرة خل النبيذ الأبيض أو 2-3 ملاعق كبيرة عصير ليمون","2 ملعقة كبيرة خميرة غذائية","ملح + فلفل حسب الرغبة","250 جرامًا (½ رطل) سباغيتي أو معكرونة من اختيارك","ثوم معمر (شيف) طازج أو ريحان طازج أو زعتر طازج أو نعناع طازج أو أعشاب من اختيارك","جبن بارميزان نباتي","قشر ليمون وفلاكس الفلفل الحار وزيت زيتون"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع التحميص بالهواء الساخن وبطّن صينية خبز بورق الزبدة. (إذا لم يكن لديك فرن بالهواء الساخن، فأتح وقتًا أطول للتحميص.)","قشّر الشمندر وقطّعه إلى مكعبات صغيرة بحجم نصف بوصة ورتّبها في طبقة واحدة على الصينية مع البصل المقطع أرباعًا وفصوص الثوم. حمّص الخضار لمدة 25-30 دقيقة، حتى تصبح ذهبية ويلين الشمندر عند غرزه بالشوكة.","في هذه الأثناء، اغلِ قدرًا كبيرًا من الماء المملح بسخاء واسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها لكن احتفظ بحوالي ½ كوب من ماء المعكرونة وضعه جانبًا. أعد المعكرونة المصفّاة إلى القدر.","بحلول هذا الوقت، يجب أن تكون الخضار جاهزة، فأضفها إلى الخلاط مع جميع مكونات الصلصة المتبقية واخلطها حتى تصبح ناعمة وكريمية. وإذا لزم الأمر، أضف بعض ماء المعكرونة المحتفظ به لتخفيف الصلصة. ثم اسكب الصلصة في القدر مع المعكرونة وقلّب حتى تتغطى بالتساوي.","قدّمها مع التزيين الذي تختاره."],
["ملّح ماء المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اسلق المعكرونة حتى تصل إلى درجة \"الدنتي\". لا تُفرط في سلقها! تعني \"الدنتي\" أن المعكرونة لا تزال متماسكة بعد الطهي، مما يعطي قوامًا مثاليًا في كل لقمة. لتتأكد من أن المعكرونة لا تفرط في النضج، ابدأ بتذوقها قبل بضع دقائق من الوقت المذكور على العبوة. يجب أن تكون طرية لكنها لا تزال متماسكة.","احتفظ ببعض ماء المعكرونة عند تصفية المعكرونة المطبوخة لتخفيف الصلصة عند الحاجة.","إذا لم يكن لديك خلاط قوي عالي السرعة، فانقع الكاجو في ماء ساخن لمدة 20 دقيقة أولًا، ثم صفّه واستخدمه حسب التعليمات.","يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام. لا أنصح بوضع المعكرونة في الفريزر لأن ذلك يغيّر قوامها. ومع ذلك، إذا كنت تحضّر كمية إضافية من الصلصة، فيمكن تجميد الصلصة في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"For garnish (optional)":"للتزيين (اختياري)"})
R(9508036,"دقيق الأرز البني - البديل المثالي الخالي من الغلوتين!",
"دقيق الأرز البني سهل التحضير في المنزل وهو بديل رائع لخيار خالٍ من الغلوتين! كما أنه اقتصادي ويحتاج إلى مكون واحد فقط.",
"4 أكواب","حصة واحدة",
["الكمية المطلوبة من الأرز البني، وعادةً أحضّر حوالي 4 أكواب في كل مرة."],
["ضع الأرز في خلاط قوي واخلطه على سرعة عالية حتى تصل إلى قوام الدقيق.","استخدمه بدلًا من دقيق القمح في وصفاتك المفضلة."],
["احفظ أي دقيق متبقٍ في وعاء محكم الإغلاق في الخزانة لاستخدامه عند الحاجة. المعلومات الغذائية لحوالي ½ كوب من الدقيق."])
R(9508489,"خبز البرجر النباتي من القمح الكامل",
"خبز برجر نباتي صحي مصنوع من دقيق القمح الكامل، بدون زيت أو زبدة أو بيض أو خميرة!",
"6 أرغفة خبز","حصة واحدة",
["270 جرامًا من دقيق القمح الكامل، أي حوالي 2¼ كوب (بالإضافة إلى المزيد للرش)","2 ملعقة صغيرة بيكنج باودر","¼ ملعقة صغيرة بيكربونات الصوديوم","1 ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق الثوم، اختياري","¼ كوب صلصة التفاح غير المحلاة","2 ملعقة كبيرة طحينة","⅔ كوب حليب الصويا غير المحلى أو حليب اللوز أو حليب نباتي من اختيارك","2 ملعقة كبيرة حليب الصويا غير المحلى أو حليب نباتي من اختيارك","½ ملعقة صغيرة شراب القيقب","½ ملعقة كبيرة سمسم","½ ملعقة كبيرة بذور الخشخاش"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية) وبطّن صينية خبز بورق الزبدة.","اغربل جميع المكونات الجافة في وعاء خلط كبير. ثم أضف المكونات السائلة إلى الوعاء نفسه وقلّب حتى تحصل على كتلة عجين. ستكون لزجة قليلًا.","انثر بعض الدقيق على لوح تقطيع نظيف أو سطح العمل. ثم ضع كتلة العجين فوقه واعجنها لمدة 30-45 ثانية، مع نثر مزيد من الدقيق عند الحاجة. لا تُفرط في العجن.","الآن قسّم العجين إلى 6 قطع متساوية وشكّل كل قطعة على هيئة قرص مستدير مفلطح وضعها على الصينية المجهزة.","اختياري: اخلط ملعقتين كبيرتين من الحليب النباتي مع شراب القيقب في وعاء صغير وادهن به كل رغيف من خبز البرجر النباتي. ثم انثر عليه البذور.","اخبزها في الفرن المسخن مسبقًا لمدة 22-25 دقيقة، حتى تصبح ذهبية. ثم أخرجها من الفرن واتركها لتبرد قليلًا واستمتع بها."],
["زِن الدقيق للحصول على أدق النتائج. فاغتراف الدقيق من الكيس بأكواب القياس عادةً ما يؤدي إلى استخدام كمية زائدة منه، وسينتج عن ذلك نتيجة جافة وكثيفة. لا تُفرط في عجن العجين. فالإفراط في العجن قد يعطي نتيجة كثيفة ومطاطية. للحصول على خبز أطرى، استخدم دقيق القمح الكامل الأبيض المعروف أيضًا بدقيق معجنات القمح الكامل. أو جرّب 50 بالمئة من دقيق القمح الكامل و50 بالمئة من الدقيق الأبيض متعدد الاستخدامات غير المبيّض. طعم خبز الهامبرغر النباتي هذا أفضل في اليوم نفسه الذي يُحضَّر فيه، لكن يمكنك حفظه في درجة حرارة الغرفة في كيس بسحّاب لمدة 2-3 أيام. أو جمّده في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر وأذِبه عند الحاجة."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة","Optional Vegan Egg Wash + Topping":"طلاء نباتي بديل للبيض + إضافات (اختياري)"})
R(9515780,"معكرونة بالجبن النباتية بقرع الباترنت [خالية من الزيت]",
"معكرونة بالجبن نباتية بقرع الباترنت مفيدة وغنية بالنكهة ولذيذة!",
"6 حصص","حصة واحدة",
["450 جرامًا معكرونة مكرونة (ماكاروني) أو كافاتابي أو من اختيارك، خالية من الغلوتين إن أردت","2 رطل قرع باترنت مقشّر ومقطع إلى مكعبات بحجم 1 بوصة، حوالي 5 أكواب مكعبات","¼ كوب كاجو نيء","½ كوب خميرة غذائية","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة بابريكا مدخنة","¾-1 كوب حليب الكاجو غير المحلى أو حليب من اختيارك","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","جبن بارميزان نباتي","مريمية طازجة","بابريكا مدخنة"],
["اغلِ قدرًا كبيرًا من الماء المملح واسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها وأعدها إلى القدر وضعها جانبًا.","في هذه الأثناء، ضع القرع في قدر صغير وغطِّه بالماء واتركه يغلي لمدة 8 دقائق، أو حتى تُغرز فيه الشوكة بسهولة. ثم صفّه وضعه في الخلاط مع جميع مكونات الصلصة المتبقية، مبتدئًا بـ ¾ كوب من الحليب. اخلط حتى يصبح ناعمًا، وأضف مزيدًا من الحليب عند الحاجة للحصول على قوام أخف.","ثم اسكب الصلصة فوق المعكرونة وقلّب جيدًا وقدّم مع أي تزيين تحبه. (احتفظ بكوب إلى كوبين من الصلصة إذا أردت إضافة المزيد فوق كل طبق عند التقديم.)"],
["ملّح ماء المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة. إذا لم يكن لديك خلاط قوي، فأضف الكاجو إلى القدر نفسه مع القرع واتركه يغلي حتى ينضج القرع. فهذا سيلين الكاجو ويساعد على خلطه بشكل أنعم. قد تحتاج إلى كمية أكثر أو أقل من الحليب بحسب حجم القرع. وعندما تبقى المعكرونة مع الصلصة، ستواصل امتصاصها. لذا، إذا كنت تخطط لحفظ المتبقي، فاحتفظ بكوب من الصلصة في وعاء منفصل قبل خلطها مع المعكرونة. أضف الصلصة المحتفظ بها إلى مقلاة مع المعكرونة المتبقية عند إعادة التسخين لإعادتها إلى قوام كريمي. يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام. يمكنك تجميد الصلصة لمدة تصل إلى 3 أشهر في وعاء محكم الإغلاق مناسب للتجميد. لا أنصح بتجميد المعكرونة لأن ذلك يغيّر القوام."],
{"For the Sauce":"للصلصة","For Garnish (optional)":"للتزيين (اختياري)"})
